import os
import sys
import xml.dom.minidom as minidom

W = "unpacked"


def ns(tag):
    return tag.split("}")[-1]


def collect_text(el):
    parts = []
    for node in el.childNodes:
        if node.nodeType == node.ELEMENT_NODE:
            t = ns(node.tagName)
            if t == "t":
                parts.append(node.firstChild.data if node.firstChild else "")
            elif t == "delText":
                parts.append("[" + (node.firstChild.data if node.firstChild else "") + "]")
            elif t == "ins":
                parts.append("+INS:")
                parts.append(collect_text(node))
            elif t == "del":
                parts.append("-DEL:")
                parts.append(collect_text(node))
            elif t == "r":
                parts.append(collect_text(node))
            elif t == "hyperlink":
                parts.append(collect_text(node))
            elif t == "tab":
                parts.append("\t")
            elif t == "br":
                parts.append(" <br/> ")
            elif t == "drawing":
                parts.append(" [IMAGE] ")
            elif t == "pict":
                parts.append(" [PICT] ")
    return "".join(parts)


def list_dir(start, prefix=""):
    for name in sorted(os.listdir(start)):
        p = os.path.join(start, name)
        if os.path.isdir(p):
            list_dir(p, prefix + name + "/")
        else:
            print("FILE:", prefix + name)


print("=== CWD ===")
print(os.getcwd())
print()
print("=== UNPACKED FILE TREE (top levels) ===")
for name in sorted(os.listdir(W)):
    p = os.path.join(W, name)
    if os.path.isdir(p):
        print("DIR:", name)
        for inner in sorted(os.listdir(p))[:40]:
            ip = os.path.join(p, inner)
            if os.path.isdir(ip):
                print("  DIR:", inner)
                for inn in sorted(os.listdir(ip))[:40]:
                    print("    ", inn)
            else:
                print("  ", inner)
    else:
        print("FILE:", name)

doc_path = os.path.join(W, "word", "document.xml")
print()
print("=== DOCUMENT STRUCTURE ===")
dom = minidom.parse(doc_path)
body = dom.getElementsByTagName("w:body")[0]
idx = 0
for child in body.childNodes:
    if child.nodeType != child.ELEMENT_NODE:
        continue
    tag = ns(child.tagName)
    if tag == "p":
        styles = []
        pPr = child.getElementsByTagName("w:pPr")
        if pPr:
            ps = pPr[0].getElementsByTagName("w:pStyle")
            if ps:
                styles.append("style=" + ps[0].getAttribute("w:val"))
            num = pPr[0].getElementsByTagName("w:numPr")
            if num:
                ilvl = num[0].getElementsByTagName("w:ilvl")
                nid = num[0].getElementsByTagName("w:numId")
                styles.append(
                    "numIlvl=" + (ilvl[0].getAttribute("w:val") if ilvl else "?")
                    + " numId=" + (nid[0].getAttribute("w:val") if nid else "?")
                )
        text = collect_text(child).strip()
        line = child.getElementsByTagName("w:t")
        if text or styles:
            print(f"P[{idx}] {', '.join(styles)} :: {text[:180]}")
    elif tag == "tbl":
        print(f"TBL[{idx}] (table present)")
    elif tag == "sectPr":
        print(f"SECT[{idx}] <sectPr> body section properties")
    elif tag == "bookmarkStart":
        print(f"BMK[{idx}] bookmarkStart name={child.getAttribute('w:name')}")
    elif tag == "bookmarkEnd":
        pass
    else:
        print(f"OTHER[{idx}] <{tag}>")
    idx += 1

print()
print("=== styles.xml paragraph/heading styles ===")
styles_path = os.path.join(W, "word", "styles.xml")
if os.path.exists(styles_path):
    sdom = minidom.parse(styles_path)
    for st in sdom.getElementsByTagName("w:style"):
        stype = st.getAttribute("w:type")
        sid = st.getAttribute("w:styleId")
        nm = st.getElementsByTagName("w:name")
        nmv = nm[0].getAttribute("w:val") if nm else ""
        if stype in ("paragraph",) or sid.startswith("Heading"):
            print(f"  {stype:10s} {sid:20s} {nmv}")
